import math
import mmh3
import threading
from typing import List, Optional

class CompressedBloomFilter:
    """Sliding-window compressed Bloom filter for efficient P2P gossip message deduplication."""
    def __init__(self, capacity: int = 10000, error_rate: float = 0.01):
        self.capacity = capacity
        self.error_rate = error_rate
        self.num_bits = int(-capacity * math.log(error_rate) / (math.log(2) ** 2))
        self.num_hashes = max(1, int((self.num_bits / capacity) * math.log(2)))

        # Byte array for bit storage, ensuring < 64KB footprint
        self.num_bytes = math.ceil(self.num_bits / 8)
        if self.num_bytes > 65536:
            # Cap at 64KB for strict memory compliance
            self.num_bytes = 65536
            self.num_bits = self.num_bytes * 8

        self.bit_array = bytearray(self.num_bytes)
        self._lock = threading.Lock()
        self._count = 0

    def _get_indexes(self, item: str) -> List[int]:
        indexes = []
        for i in range(self.num_hashes):
            digest = mmh3.hash(item, i)
            indexes.append(abs(digest) % self.num_bits)
        return indexes

    def add(self, item: str) -> None:
        with self._lock:
            for bit_index in self._get_indexes(item):
                byte_idx = bit_index // 8
                bit_offset = bit_index % 8
                self.bit_array[byte_idx] |= (1 << bit_offset)
            self._count += 1
            if self._count > self.capacity:
                self.clear()

    def __contains__(self, item: str) -> bool:
        with self._lock:
            for bit_index in self._get_indexes(item):
                byte_idx = bit_index // 8
                bit_offset = bit_index % 8
                if not (self.bit_array[byte_idx] & (1 << bit_offset)):
                    return False
            return True

    def clear(self) -> None:
        with self._lock:
            for i in range(len(self.bit_array)):
                self.bit_array[i] = 0
            self._count = 0

    def memory_usage_bytes(self) -> int:
        return len(self.bit_array)

from typing import Optional
from gossipmesh.p2p.dedup import CompressedBloomFilter

class GossipTransport:
    """P2P transport layer incorporating compressed Bloom filter message deduplication."""
    def __init__(self, capacity: int = 10000, error_rate: float = 0.01):
        self.dedup_filter = CompressedBloomFilter(capacity=capacity, error_rate=error_rate)

    def should_process_message(self, message_id: str) -> bool:
        """Checks if a message ID has been seen before. If not, records it and returns True."""
        if message_id in self.dedup_filter:
            return False
        self.dedup_filter.add(message_id)
        return True

    def reset_dedup(self) -> None:
        self.dedup_filter.clear()

import unittest
import threading
from gossipmesh.p2p.dedup import CompressedBloomFilter
from gossipmesh.p2p.transport import GossipTransport

class TestCompressedBloomFilter(unittest.TestCase):
    def test_bloom_filter_basic(self):
        bf = CompressedBloomFilter(capacity=1000, error_rate=0.01)
        self.assertLessEqual(bf.memory_usage_bytes(), 65536)

        msg_id = "msg_abc123"
        self.assertNotIn(msg_id, bf)
        bf.add(msg_id)
        self.assertIn(msg_id, bf)

    def test_sliding_window_reset(self):
        bf = CompressedBloomFilter(capacity=5, error_rate=0.01)
        for i in range(6):
            bf.add(f"msg_{i}")
        # Capacity exceeded, buffer should clear
        self.assertNotIn("msg_0", bf)

    def test_transport_deduplication(self):
        transport = GossipTransport(capacity=100, error_rate=0.01)
        msg_id = "unique_gossip_id"

        self.assertTrue(transport.should_process_message(msg_id))
        self.assertFalse(transport.should_process_message(msg_id))

    def test_concurrency_safety(self):
        bf = CompressedBloomFilter(capacity=5000, error_rate=0.01)
        def worker(start: int):
            for i in range(start, start + 100):
                bf.add(f"concurrent_{i}")

        threads = [threading.Thread(target=worker, args=(i * 100,)) for i in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        self.assertIn("concurrent_450", bf)

if __name__ == "__main__":
    unittest.main()
